#pragma once

#include "Vector.h"
#include "swroom.h"

class CSWRoomSurfaceMesh;
class CSWRoomSurfaceMeshHitInfo;
struct CWalkHitInfo;

class CSWSRoom : public CSWRoom {
public:
    CSWSRoom();

    // <VTABLE-GEN: binary ground truth (_ZTV) — regenerated by tools/hoist_headers.py; do not edit inside markers */
    //   primary vtable, 2 slots
    virtual ~CSWSRoom();
    // </VTABLE-GEN>

    int ClippedLineSegmentWalkable(const Vector& segStart, const Vector& segEnd, Vector& clipStart,
                                   Vector& clipEnd, float& tStart, float& tEnd, int& outFlags);
    int ComputeClippedLineSegment(Vector segStart, Vector segEnd, Vector& clipStart, Vector& clipEnd,
                                  int& outFlags);
    int    GetAdjacentRoom(int edgeIdx);

    // The four whole-room walkmesh operations the area's room loader drives, in call order. Each returns
    // early for a wildcard room name, which has no walkmesh to load, and otherwise forwards to the room
    // mesh. The weld and adjacency calls both pass the other room's mesh plus both world origins, so the
    // mesh-level call can rebase the neighbour's vertices into this room's space.
    int  LoadWalkMesh(int bForceText);
    void TransformToWorld();
    int  WeldRoom(CSWSRoom& room, float fTolerance);
    void ComputeMeshNormals();
    int  SetRoomAdjacency(CSWSRoom& room, int nThisRoom, int nOtherRoom);
    Vector GetNormalOfPoint(int nRoom);
    // Locates the walkmesh triangle under a point across the whole room and answers the up vector,
    // falling back to (0,0,1) for -1 and for a mesh with no normal array yet.
    Vector GetNormalOfPoint(Vector vPoint);
    // Walkmesh segment probe. The float refs are const references, so callers pass addresses of locals.
    int NoNonWalkPolysOnRoom(const Vector& a, const Vector& b, const float& f1, const float& f2,
                             const float& f3, CWalkHitInfo* hitInfo);
    // Line-of-sight probe across this room's walkmesh. The object-id out-parameter carries the blocker id
    // from the area-level query but the body never uses it. Returns 1 when the segment is clear.
    int ClearLineOfSight(Vector from, Vector to, Vector* pHitPoint, unsigned long long* pObjectId);
    int CheckAABBAll(Vector boxMin, Vector boxMax, CSWRoomSurfaceMeshHitInfo& hitInfo);
#if KOTOR1  // K1: the boxes by value
    int CheckAABBWalkable(Vector boxMin, Vector boxMax, CSWRoomSurfaceMeshHitInfo& hitInfo);
#else
    int CheckAABBWalkable(const Vector& boxMin, const Vector& boxMax,
                          CSWRoomSurfaceMeshHitInfo& hitInfo);
#endif

    // Two height queries over the walkmesh. The (int, Vector) form takes the room index the area already
    // resolved; the (Vector, int) form takes 0.
    float ComputeHeight(int triangle, Vector point);
    float ComputeHeight(Vector point, int flags);

    CSWRoomSurfaceMesh* m_pSurfaceMesh;
    char                _pad48[0x58 - 0x48];
};
